The server's error payload for a streaming resume attempt that fails with HTTP 409 (checkpoint mismatch) includes the following JSON schema:

```json
{
  "title": "Error Response",
  "type": "object",
  "properties": {
    "error": {
      "type": "object",
      "properties": {
        "code": {
          "type": "integer",
          "description": "The error code",
          "minimum": 409
        },
        "message": {
          "type": "string",
          "description": "The error message"
        },
        "details": {
          "type": "object",
          "description": "Additional error details",
          "properties": {
            "resume_details": {
              "type": "object",
              "description": "Additional resume details",
              "properties": {
                "checkpoint": {
                  "type": "object",
                  "description": "The checkpoint details",
                  "properties": {
                    "offset": {
                      "type": "integer",
                      "description": "The offset of the checkpoint"
                    },
                    "resume_token": {
                      "type": "string",
                      "description": "The resume token associated with the checkpoint"
                    }
                  }
                },
                "resume_status": {
                  "type": "string",
                  "description": "The status of the resume attempt"
                }
              }
            }
          }
        }
      }
    }
  }
}
